					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "grpc://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "OTLP default",
